// Cross-checks the agent's local ACI receipt verification (JCS canonicalizer +
// Ed25519 verify + model/response-hash extraction, agent/src/phala.ts) against
// fixtures/receipt_vectors.json -- real byte-exact vectors generated by
// receipt-verifier/tests/export_fixture.rs via verify_receipt_core (the same
// Rust code path the Stylus IReceiptVerifier.verifyReceipt runs onchain), not
// hand-computed or mocked. If this agent's canonicalizer disagreed with the
// Rust crate's, or if @noble/curves' ed25519.verify disagreed with the
// dalek/Stylus verifier, this test would fail; it does not, so both sides
// agree on the same bytes and the same verdict.
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { modelHash } from '../src/digest.ts';
import { receiptSigningInput, verifyReceiptLocally, type ReceiptDocument } from '../src/phala.ts';

const fixturesPath = fileURLToPath(new URL('../../fixtures/receipt_vectors.json', import.meta.url));
const fixtures = JSON.parse(readFileSync(fixturesPath, 'utf8')) as {
  pubkey: string;
  honest: FixtureVector;
  model_swap: FixtureVector;
};

type FixtureVector = {
  receipt_bytes_hex: string;
  signature_hex: string;
  requested_model_hash: string;
  served_model_hash: string;
  response_hash: string;
};

function hexToUtf8(hex: string): string {
  const stripped = hex.startsWith('0x') ? hex.slice(2) : hex;
  return Buffer.from(stripped, 'hex').toString('utf8');
}

/// Reconstruct the full served document (receiptSigningInput expects a
/// `signature` member present so it can strip it) from the fixture's
/// signing-input bytes plus its detached signature -- the fixture exports
/// signing input and signature separately since that is what
/// IReceiptVerifier.verifyReceipt actually takes as two calldata arguments,
/// not a served JSON document. Re-adding `signature` and re-stripping it via
/// receiptSigningInput is exactly what round-trips back to the original bytes
/// if (and only if) this canonicalizer sorts/serializes identically to the
/// Rust crate's.
function fullDocument(vector: FixtureVector): ReceiptDocument {
  const withoutSignature = JSON.parse(hexToUtf8(vector.receipt_bytes_hex)) as Omit<ReceiptDocument, 'signature'>;
  return { ...withoutSignature, signature: vector.signature_hex };
}

for (const [name, vector] of [
  ['honest', fixtures.honest],
  ['model_swap', fixtures.model_swap],
] as const) {
  test(`${name}: receiptSigningInput round-trips byte-for-byte to the Rust-generated fixture`, () => {
    const doc = fullDocument(vector);
    const computed = receiptSigningInput(doc);
    const computedHex = `0x${Buffer.from(computed).toString('hex')}`;
    assert.equal(computedHex, vector.receipt_bytes_hex);
  });

  test(`${name}: ed25519 signature verifies under the fixture pubkey`, () => {
    const doc = fullDocument(vector);
    const result = verifyReceiptLocally(doc, fixtures.pubkey);
    assert.equal(result.ok, true, result.reason);
  });

  test(`${name}: extracted requested/served model hashes match the fixture's own`, () => {
    const doc = fullDocument(vector);
    const result = verifyReceiptLocally(doc, fixtures.pubkey);
    assert.equal(result.ok, true, result.reason);
    assert.equal(modelHash(result.requestedModel), vector.requested_model_hash);
    assert.equal(modelHash(result.servedModel!), vector.served_model_hash);
  });

  test(`${name}: extracted response hash matches the fixture's response_hash`, () => {
    const doc = fullDocument(vector);
    const result = verifyReceiptLocally(doc, fixtures.pubkey);
    assert.equal(result.ok, true, result.reason);
    assert.equal(`0x${result.responseHashHex}`, vector.response_hash);
  });
}

test('model_swap: requested and served model hashes differ (this is the case a real client must refuse before signing)', () => {
  const doc = fullDocument(fixtures.model_swap);
  const result = verifyReceiptLocally(doc, fixtures.pubkey);
  assert.equal(result.ok, true, result.reason);
  assert.notEqual(modelHash(result.requestedModel), modelHash(result.servedModel!));
  assert.equal(result.requestedModel, 'requested-model');
  assert.equal(result.servedModel, 'served-model');
});

test('honest: requested and served model hashes are equal (the case a client should pay)', () => {
  const doc = fullDocument(fixtures.honest);
  const result = verifyReceiptLocally(doc, fixtures.pubkey);
  assert.equal(result.ok, true, result.reason);
  assert.equal(result.requestedModel, result.servedModel);
});

// Mutation-style check: a check that cannot fail is worse than no check. Flip
// one byte of the signature and confirm verifyReceiptLocally actually goes
// from ok=true to ok=false, proving the Ed25519 check is load-bearing and not
// vacuously true.
test('tampered signature: verifyReceiptLocally goes from ok=true to ok=false (mutation-proof)', () => {
  const doc = fullDocument(fixtures.honest);
  const genuine = verifyReceiptLocally(doc, fixtures.pubkey);
  assert.equal(genuine.ok, true, genuine.reason);

  const sigBytes = Buffer.from(doc.signature.slice(2), 'hex');
  sigBytes[0] ^= 0xff;
  const tampered: ReceiptDocument = { ...doc, signature: `0x${sigBytes.toString('hex')}` };
  const result = verifyReceiptLocally(tampered, fixtures.pubkey);
  assert.equal(result.ok, false);
});

// Mutation-style check for the pubkey side of the same gate: a genuine
// receipt checked against the WRONG pubkey must also fail, not just a
// tampered signature against the right one.
test('wrong pubkey: verifyReceiptLocally rejects a genuine honest receipt (mutation-proof)', () => {
  const doc = fullDocument(fixtures.honest);
  const wrongPubkey = `0x${'11'.repeat(32)}`;
  const result = verifyReceiptLocally(doc, wrongPubkey);
  assert.equal(result.ok, false);
});

// The fixture's own JSON text already has alphabetically-sorted top-level
// keys (it was generated by the Rust crate's own JCS canonicalizer), so
// JSON.parse's insertion-order preservation alone makes the round-trip tests
// above pass even with key-sorting disabled -- confirmed directly: commenting
// out canonicalizeValue's `.sort()` call still leaves every test above green.
// A real served document is not guaranteed to arrive pre-sorted (spec/aci.md:
// "any JSON encoding of the same document verifies, client MUST canonicalize
// itself"), so sorting is still required for correctness; this test proves it
// with a document built with keys in deliberately reversed order, which
// JSON.stringify-based JS object literals still preserve as insertion order.
test('receiptSigningInput sorts keys regardless of the input object\'s own key order', () => {
  const doc = fullDocument(fixtures.honest);
  const reordered: ReceiptDocument = {} as ReceiptDocument;
  // Insert every key of `doc` in reverse alphabetical order.
  for (const k of Object.keys(doc).sort().reverse()) {
    (reordered as Record<string, unknown>)[k] = (doc as unknown as Record<string, unknown>)[k];
  }
  const sortedFirst = receiptSigningInput(doc);
  const reversedFirst = receiptSigningInput(reordered);
  assert.deepEqual(Buffer.from(sortedFirst), Buffer.from(reversedFirst));
  assert.equal(`0x${Buffer.from(reversedFirst).toString('hex')}`, fixtures.honest.receipt_bytes_hex);
});
